// YARA Rule Builder — malware-detection tool for the Darknode web app.
// Build, validate and export YARA rules (meta, strings, condition) by hand.
// Copyright (c) 2026 Darknode-Official. All rights reserved.
// Fully client-side. No network, no external libraries. Rule text generated by hand.
//
// Architecture: the rule MODEL (plain object) is the single source of truth.
// Two pure functions operate on it and know nothing about the DOM:
//   buildYara(model)    -> String   (valid YARA text, ready to paste into a .yar)
//   validateYara(model) -> [{severity, message, field}]  (structured findings)
// The render layer below only edits the model and asks these two for text/findings,
// so generation and validation are auditable and testable in isolation (see __selftest).

const esc = (s) => String(s != null ? s : "").replace(/[&<>"']/g, (c) =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

function todayStr() {
  var d = new Date();
  var p = function (n) { return (n < 10 ? "0" : "") + n; };
  return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}

// ── name / identifier validation ──
var NAME_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;
var STRID_RE = /^\$[A-Za-z0-9_]*$/;
// reserved words that cannot be used as a rule name / tag
var RESERVED = {
  all: 1, and: 1, any: 1, ascii: 1, at: 1, base64: 1, base64wide: 1, condition: 1,
  contains: 1, entrypoint: 1, false: 1, filesize: 1, for: 1, fullword: 1, global: 1,
  import: 1, in: 1, include: 1, "int16": 1, "int32": 1, "int8": 1, matches: 1, meta: 1,
  nocase: 1, not: 1, of: 1, or: 1, "private": 1, rule: 1, strings: 1, them: 1, "true": 1,
  "uint16": 1, "uint32": 1, "uint8": 1, wide: 1, xor: 1
};

// text / regex string modifiers (what applies to each type)
var TEXT_MODS = ["nocase", "wide", "ascii", "fullword", "xor", "base64"];
var REGEX_MODS = ["nocase", "wide", "ascii", "fullword"];

// condition helper presets
var COND_PRESETS = [
  ["any of them", "any of them"],
  ["all of them", "all of them"],
  ["any of ($s*)", "any of ($s*)"],
  ["2 of them", "2 of them"],
  ["MZ header", "uint16(0) == 0x5A4D"],
  ["filesize < 1MB", "filesize < 1MB"],
  ["$s1 and $s2", "$s1 and $s2"]
];

