// ════════════════════════════════════════════════════════════════════════
//  PURE LAYER — model helpers, generator, validator. No DOM access here.
// ════════════════════════════════════════════════════════════════════════

// strings that actually carry a value (empties are omitted from output).
function activeStrings(st) {
  return (st.strings || []).filter(function (s) { return s && s.value && String(s.value).trim() !== ""; });
}

// ── hex string helpers ──
// normalize a hex string: collapse whitespace, uppercase bytes, keep ?? and () | -
function normalizeHex(v) {
  return String(v || "")
    .replace(/[{}]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toUpperCase();
}
// validate hex body: allow hex digits, ?? wildcards, jumps [n], [n-m], alternation ( | ), whitespace
function hexProblems(raw) {
  var v = normalizeHex(raw);
  if (!v) return ["hex string is empty"];
  var probs = [];
  // strip jumps and groups for the byte check
  var tokens = v.split(/\s+/);
  tokens.forEach(function (t) {
    // allow group/jump tokens
    if (/^[()|]$/.test(t)) return;
    if (/^\[\d*(-\d*)?\]$/.test(t)) return;
    // split leading/trailing brackets attached to a byte
    var core = t.replace(/^[()]+|[()]+$/g, "");
    if (core === "") return;
    // each remaining token should be a 2-char byte or ?? pair (may include single-nibble wildcard like 4?)
    if (!/^([0-9A-F?]{2})$/.test(core)) {
      probs.push("invalid hex token '" + t + "' (expect byte pairs like 4D or wildcards like ?? / 4?)");
    }
  });
  // balanced parentheses
  var depth = 0;
  for (var i = 0; i < v.length; i++) {
    if (v[i] === "(") depth++;
    else if (v[i] === ")") depth--;
    if (depth < 0) break;
  }
  if (depth !== 0) probs.push("unbalanced parentheses in hex group");
  return probs;
}

// ── string line builders ──
function activeMods(s) {
  var avail = s.type === "regex" ? REGEX_MODS : TEXT_MODS;
  var out = [];
  avail.forEach(function (m) { if (s.mods && s.mods[m]) out.push(m); });
  return out;
}
function escTextValue(v) {
  // YARA text strings are C-style double-quoted; escape backslash, quote and control chars.
  return String(v || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"')
    .replace(/\t/g, "\\t").replace(/\r/g, "\\r").replace(/\n/g, "\\n");
}
function stringLine(s) {
  var id = (s.id || "$s").trim();
  if (s.type === "hex") {
    return id + " = { " + normalizeHex(s.value) + " }";
  }
  if (s.type === "regex") {
    var pat = String(s.value || "").replace(/^\/|\/$/g, "");
    var mods = activeMods(s);
    return id + " = /" + pat + "/" + (mods.length ? " " + mods.join(" ") : "");
  }
  // text
  var m = activeMods(s);
  return id + ' = "' + escTextValue(s.value) + '"' + (m.length ? " " + m.join(" ") : "");
}

// count `{`/`}` that act as block delimiters, skipping those inside double-quoted
// text strings and regex literals (where braces are literal characters).
function structuralBracesBalanced(text) {
  var depth = 0, inStr = false, inRegex = false, escaped = false;
  for (var i = 0; i < text.length; i++) {
    var c = text[i];
    if (inStr) {
      if (escaped) escaped = false;
      else if (c === "\\") escaped = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (inRegex) {
      if (escaped) escaped = false;
      else if (c === "\\") escaped = true;
      else if (c === "/") inRegex = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === "/") { inRegex = true; continue; }
    if (c === "{") depth++;
    else if (c === "}") { depth--; if (depth < 0) return false; }
  }
  return depth === 0;
}

// ── generator: model -> valid YARA text ──
export function buildYara(st) {
  st = st || {};
  var IND = "    ";
  var L = [];
  var tags = String(st.tags || "").trim().split(/\s+/).filter(Boolean);
  var header = "rule " + (st.name || "unnamed_rule");
  if (tags.length) header += " : " + tags.join(" ");  // omit `: tags` when none
  L.push(header);
  L.push("{");

  // meta block (only lines with values)
  var meta = [];
  if (st.author && st.author.trim()) meta.push(["author", st.author.trim()]);
  if (st.description && st.description.trim()) meta.push(["description", st.description.trim()]);
  if (st.date && st.date.trim()) meta.push(["date", st.date.trim()]);
  if (st.reference && st.reference.trim()) meta.push(["reference", st.reference.trim()]);
  if (st.hash && st.hash.trim()) meta.push(["hash", st.hash.trim()]);
  if (meta.length) {
    L.push(IND + "meta:");
    meta.forEach(function (kv) {
      L.push(IND + IND + kv[0] + ' = "' + escTextValue(kv[1]) + '"');
    });
  }

  // strings block
  var strs = activeStrings(st);
  if (strs.length) {
    L.push(IND + "strings:");
    strs.forEach(function (s) { L.push(IND + IND + stringLine(s)); });
  }

  // condition block (always present)
  L.push(IND + "condition:");
  L.push(IND + IND + (st.condition && st.condition.trim() ? st.condition.trim() : "any of them"));

  L.push("}");
  return L.join("\n") + "\n";
}

// ── validator: model -> structured findings ──
// Each finding is {severity:'error'|'warning', message:String, field:String|null}.
// Errors mean the generated rule would be rejected / wrong; warnings are advisory.
export function validateYara(st) {
  st = st || {};
  var out = [];
  function err(message, field) { out.push({ severity: "error", message: message, field: field || null }); }
  function warn(message, field) { out.push({ severity: "warning", message: message, field: field || null }); }

  // rule name
  var nm = (st.name || "").trim();
  if (!nm) {
    err("Rule name is required.", "name");
  } else if (!NAME_RE.test(nm)) {
    err("Rule name '" + nm + "' is not a valid identifier (letters, digits, underscore; cannot start with a digit).", "name");
  } else if (RESERVED[nm.toLowerCase()]) {
    err("Rule name '" + nm + "' is a reserved YARA keyword.", "name");
  }

  // tags must each be valid identifiers (and not reserved words)
  String(st.tags || "").trim().split(/\s+/).filter(Boolean).forEach(function (t) {
    if (!NAME_RE.test(t)) err("Tag '" + t + "' is not a valid identifier.", "tags");
    else if (RESERVED[t.toLowerCase()]) warn("Tag '" + t + "' is a reserved YARA keyword.", "tags");
  });

  // strings
  var strs = activeStrings(st);
  var ids = [];
  strs.forEach(function (s, i) {
    var id = (s.id || "").trim();
    var where = "string:" + (id || ("#" + (i + 1)));
    if (!id) err("String #" + (i + 1) + " is missing an identifier.", where);
    else if (!STRID_RE.test(id)) err("String identifier '" + id + "' must start with $ and use only letters, digits or underscore.", where);
    else if (ids.indexOf(id) >= 0) err("Duplicate string identifier '" + id + "'.", where);
    else ids.push(id);

    if (s.type === "hex") {
      hexProblems(s.value).forEach(function (p) { err("String " + (id || ("#" + (i + 1))) + ": " + p, where); });
    } else if (s.type === "regex") {
      try { new RegExp(String(s.value).replace(/^\/|\/$/g, "")); }
      catch (e) { err("String " + (id || ("#" + (i + 1))) + ": invalid regex — " + e.message, where); }
    } else {
      var tv = String(s.value || "");
      if (tv.trim().length > 0 && tv.length < 3) {
        warn("String " + (id || ("#" + (i + 1))) + " text '" + tv + "' is very short and may match too broadly.", where);
      }
    }
  });

  // condition
  var cond = (st.condition || "").trim();
  if (!cond) {
    err("A condition is required.", "condition");
  } else {
    // referenced $ identifiers must exist (unless a wildcard like $s* or $*)
    var refs = cond.match(/\$[A-Za-z0-9_]*\*?/g) || [];
    refs.forEach(function (r) {
      if (r === "$" || /\*$/.test(r)) {
        // wildcard — check at least one string matches the prefix
        var base = r.replace(/\*$/, "");
        var ok = base === "$" ? ids.length > 0 : ids.some(function (id) { return id.indexOf(base) === 0; });
        if (!ok) err("Condition wildcard '" + r + "' matches no defined string.", "condition");
        return;
      }
      if (ids.indexOf(r) < 0) err("Condition references undefined string '" + r + "'.", "condition");
    });
    // a string-free condition is only valid when no strings are referenced
    if (!strs.length && refs.length) {
      err("Condition references strings but no strings are defined.", "condition");
    }
    // "them" / "of them" implicitly needs strings
    if (!strs.length && /\bthem\b/.test(cond)) {
      err('Condition uses "them" but no strings are defined.', "condition");
    }
  }

  // need at least a string or a string-free condition
  if (!strs.length && (!cond || /\$/.test(cond))) {
    err("Define at least one string, or use a condition that does not reference strings (e.g. uint16(0) == 0x5A4D).", "condition");
  }

  // balanced braces in the full generated rule — counted structurally so that
  // literal braces inside quoted text strings and regex quantifiers (e.g. {2})
  // are not mistaken for block delimiters.
  if (!structuralBracesBalanced(buildYara(st))) {
    err("Unbalanced braces in generated rule.");
  }

  // balanced parentheses in condition
  var cdepth = 0, badP = false;
  for (var j = 0; j < cond.length; j++) {
    if (cond[j] === "(") cdepth++;
    else if (cond[j] === ")") cdepth--;
    if (cdepth < 0) { badP = true; break; }
  }
  if (badP || cdepth !== 0) err("Unbalanced parentheses in condition.", "condition");

  return out;
}

// ── tiny self-check: build + validate the three examples ──
// Exported so it can be run in a console or a test harness; also asserts.
export function __selftest() {
  var expected = [
    ["rule Detect_PE_Executable : pe executable", "$pe = { 50 45 00 00 }", "uint16(0) == 0x5A4D and $pe"],
    ["rule Suspicious_PowerShell_Download : powershell downloader", '$ps1 = "DownloadString" nocase wide ascii', "2 of them"],
    ["rule EICAR_Test_File : test eicar", '$eicar at 0', 'hash = "275a021b']
  ];
  var ex = examples();
  var results = [];
  var allOk = true;
  ex.forEach(function (e, i) {
    var text = buildYara(e.state);
    var findings = validateYara(e.state);
    var errors = findings.filter(function (f) { return f.severity === "error"; });
    var lineOk = true;
    expected[i].forEach(function (line) {
      var present = text.indexOf(line) >= 0;
      if (!present) { lineOk = false; allOk = false; }
      console.assert(present, "YARA __selftest: example " + (i + 1) + " (" + e.name + ") is missing expected line: " + line);
    });
    if (errors.length) { allOk = false; }
    console.assert(errors.length === 0, "YARA __selftest: example " + (i + 1) + " (" + e.name + ") reported validation errors:", errors);
    results.push({ example: e.name, linesPresent: lineOk, errorCount: errors.length, warningCount: findings.length - errors.length });
  });
  return { ok: allOk, results: results };
}

