// ════════════════════════════════════════════════════════════════════════
//  RENDER LAYER — owns the DOM; delegates all generation/validation to the
//  pure functions above and only ever edits the model.
// ════════════════════════════════════════════════════════════════════════
export function renderYaraBuilder(main) {
  var state = emptyModel();

  function toast(msg) {
    if (typeof window.showToast === "function") window.showToast(msg);
  }

  // next free $sN identifier
  function nextStringId() {
    var n = 1;
    var used = {};
    state.strings.forEach(function (s) { used[s.id] = 1; });
    while (used["$s" + n]) n++;
    return "$s" + n;
  }

  var TYPE_OPTS = [["text", "text"], ["hex", "hex"], ["regex", "regex"]];

  main.innerHTML = YR_CSS +
    '<div class="yr-wrap">' +
    '<div class="pg-head"><div>' +
    '<h1 class="pg-h1">YARA Rule Builder</h1>' +
    '<p class="muted pg-sub">Author, validate and export YARA rules for malware hunting. Meta, strings and condition — everything runs in your browser.</p>' +
    '</div></div>' +
    '<div class="yr-grid">' +

    // ── left column (form) ──
    '<div class="yr-col">' +

    '<div class="panel">' +
    '<div class="panel-h"><h2 class="pg-h2">Rule &amp; Metadata</h2>' +
    '<div class="yr-actions">' +
    '<button class="btn ghost yr-mini" id="yr-reset" type="button">Reset</button>' +
    '<div class="yr-sub-menu"><button class="btn ghost yr-mini" id="yr-example-btn" type="button">Load example</button>' +
    '<div class="yr-menu" id="yr-example-menu"></div></div>' +
    '</div>' +
    '</div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-name">Rule name (identifier)</label>' +
    '<input class="yr-in yr-mono" id="yr-name" placeholder="Suspicious_PowerShell_Download">' +
    '<div class="yr-warn" id="yr-name-warn"></div></div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-tags">Tags (space separated, optional)</label>' +
    '<input class="yr-in yr-mono" id="yr-tags" placeholder="trojan downloader"></div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-desc">Description</label>' +
    '<textarea class="yr-ta" id="yr-desc" placeholder="What does this rule detect?"></textarea></div>' +
    '<div class="yr-row2">' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-author">Author</label><input class="yr-in" id="yr-author" placeholder="Name or team"></div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-date">Date</label><input class="yr-in" id="yr-date" placeholder="YYYY-MM-DD"></div>' +
    '</div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-ref">Reference / URL</label><input class="yr-in" id="yr-ref" placeholder="https://attack.mitre.org/..."></div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-hash">Sample hash (optional)</label><input class="yr-in yr-mono" id="yr-hash" placeholder="sha256..."></div>' +
    '</div>' +

    '<div class="panel">' +
    '<div class="panel-h"><h2 class="pg-h2">Strings</h2>' +
    '<button class="btn ghost yr-mini" id="yr-add-str" type="button">Add string</button></div>' +
    '<div id="yr-strings"></div>' +
    '<p class="yr-hint">Text strings are double-quoted and escaped automatically. Hex accepts bytes, wildcards (??), jumps [n-m] and alternation. Regex is written between slashes.</p>' +
    '</div>' +

    '<div class="panel">' +
    '<div class="panel-h"><h2 class="pg-h2">Condition</h2></div>' +
    '<div class="yr-chips" id="yr-cond-presets"></div>' +
    '<div class="yr-field"><label class="yr-lbl" for="yr-condition">Condition expression</label>' +
    '<textarea class="yr-ta yr-mono" id="yr-condition" style="min-height:52px" placeholder="any of them"></textarea>' +
    '<p class="yr-hint">Click a preset to insert it, then edit freely. Keywords: and, or, not, of, them, at, filesize, uint16(0).</p></div>' +
    '</div>' +

    '</div>' +

    // ── right column (preview) ──
    '<div class="yr-col">' +
    '<div class="panel yr-sticky">' +
    '<div class="panel-h"><h2 class="pg-h2">YARA Rule</h2>' +
    '<div class="yr-actions">' +
    '<button class="btn ghost yr-mini" id="yr-validate" type="button">Validate</button>' +
    '<button class="btn ghost yr-mini" id="yr-copy" type="button">Copy rule</button>' +
    '<button class="btn primary yr-mini" id="yr-download" type="button">Download .yar</button>' +
    '</div></div>' +
    '<pre class="yr-code" id="yr-code"></pre>' +
    '<div class="yr-valid" id="yr-valid"></div>' +
    '</div>' +
    '</div>' +

    '</div></div>';

  // refs
  var $ = function (id) { return main.querySelector("#" + id); };
  var codePre = $("yr-code");
  var validBox = $("yr-valid");
  var nameWarn = $("yr-name-warn");
  var strWrap = $("yr-strings");

  // ── live preview + validation, debounced so typing in many fields doesn't thrash ──
  var touched = false;      // suppress findings on the pristine empty form
  var refreshTimer = null;

  function updateNameWarn() {
    var nm = (state.name || "").trim();
    if (nm && (!NAME_RE.test(nm) || RESERVED[nm.toLowerCase()])) {
      nameWarn.textContent = RESERVED[nm.toLowerCase()]
        ? "'" + nm + "' is a reserved YARA keyword."
        : "Invalid identifier — use letters, digits, underscore; cannot start with a digit.";
      nameWarn.classList.add("show");
    } else {
      nameWarn.classList.remove("show");
    }
  }

  function renderFindings(findings) {
    var errs = findings.filter(function (f) { return f.severity === "error"; });
    var warns = findings.filter(function (f) { return f.severity === "warning"; });
    if (!errs.length && !warns.length) {
      var count = activeStrings(state).length;
      validBox.innerHTML = '<div class="yr-ok">Rule looks valid. ' + count + ' string' + (count === 1 ? "" : "s") +
        ' defined, condition OK. Paste it straight into a .yar file.</div>';
      return;
    }
    var parts = [];
    if (errs.length) parts.push(errs.length + " error" + (errs.length === 1 ? "" : "s"));
    if (warns.length) parts.push(warns.length + " warning" + (warns.length === 1 ? "" : "s"));
    var head = '<div style="color:var(--mut);margin-bottom:6px">' + parts.join(", ") + " found:</div>";
    // errors first, then warnings
    var ordered = errs.concat(warns);
    var items = ordered.map(function (f) {
      var cls = f.severity === "warning" ? "yr-prob warn" : "yr-prob";
      var tag = f.severity === "warning" ? "warning" : "error";
      return '<div class="' + cls + '"><span class="yr-sev">' + tag + '</span>' + esc(f.message) + "</div>";
    }).join("");
    validBox.innerHTML = head + items;
  }

  function doRefresh() {
    refreshTimer = null;
    codePre.textContent = buildYara(state);
    updateNameWarn();
    if (touched) renderFindings(validateYara(state));
  }
  function scheduleRefresh() {
    touched = true;
    if (refreshTimer) clearTimeout(refreshTimer);
    refreshTimer = setTimeout(doRefresh, 120);
  }
  function flushRefresh() {
    if (refreshTimer) { clearTimeout(refreshTimer); refreshTimer = null; }
    doRefresh();
  }

  // ── bind metadata fields ──
  function bindInput(id, setter) {
    var el = $(id);
    el.oninput = function () { setter(el.value); scheduleRefresh(); };
    el.onchange = function () { setter(el.value); scheduleRefresh(); };
  }
  bindInput("yr-name", function (v) { state.name = v; });
  bindInput("yr-tags", function (v) { state.tags = v; });
  bindInput("yr-desc", function (v) { state.description = v; });
  bindInput("yr-author", function (v) { state.author = v; });
  bindInput("yr-date", function (v) { state.date = v.trim(); });
  bindInput("yr-ref", function (v) { state.reference = v.trim(); });
  bindInput("yr-hash", function (v) { state.hash = v.trim(); });
  bindInput("yr-condition", function (v) { state.condition = v; });

  // ── strings rendering (incremental) ──
  // Each row is bound to its string OBJECT (not an index), so adding/removing a
  // row never re-renders its siblings and leaves their caret/selection intact.
  function buildStringBlock(s) {
    var typeOpts = TYPE_OPTS.map(function (o) {
      return '<option value="' + o[0] + '"' + (o[0] === s.type ? " selected" : "") + ">" + esc(o[1]) + "</option>";
    }).join("");
    var modsHtml = "";
    if (s.type !== "hex") {
      var avail = s.type === "regex" ? REGEX_MODS : TEXT_MODS;
      modsHtml = '<div class="yr-mods">' + avail.map(function (m) {
        return '<label><input type="checkbox" class="yr-mod" data-mod="' + m + '"' +
          (s.mods && s.mods[m] ? " checked" : "") + ">" + esc(m) + "</label>";
      }).join("") + "</div>";
    }
    var placeholder = s.type === "hex" ? "4D 5A 90 00 ?? FF" :
      (s.type === "regex" ? "/evil[0-9]{2}\\.dll/" : "cmd.exe /c");
    var html = '<div class="yr-str-block">' +
      '<div class="yr-str-head">' +
      '<input class="yr-in yr-mono yr-s-id" value="' + esc(s.id) + '" placeholder="$s1">' +
      '<select class="yr-sel yr-s-type">' + typeOpts + "</select>" +
      '<textarea class="yr-str-val yr-s-value" placeholder="' + esc(placeholder) + '">' + esc(s.value) + "</textarea>" +
      '<button class="yr-iconbtn yr-del-str" type="button" title="Remove string">Remove</button>' +
      "</div>" + modsHtml + "</div>";
    var tmp = document.createElement("div");
    tmp.innerHTML = html;
    var block = tmp.firstElementChild;

    block.querySelector(".yr-s-id").oninput = function (e) { s.id = e.target.value; scheduleRefresh(); };
    block.querySelector(".yr-s-type").onchange = function (e) {
      s.type = e.target.value;
      // only this row changes (its modifier set differs) — rebuild it in place
      var nb = buildStringBlock(s);
      block.replaceWith(nb);
      scheduleRefresh();
    };
    block.querySelector(".yr-s-value").oninput = function (e) { s.value = e.target.value; scheduleRefresh(); };
    block.querySelector(".yr-del-str").onclick = function () {
      var idx = state.strings.indexOf(s);
      if (idx >= 0) state.strings.splice(idx, 1);
      block.remove();
      if (!state.strings.length) {
        var ns = { id: "$s1", type: "text", value: "", mods: {} };
        state.strings.push(ns);
        strWrap.appendChild(buildStringBlock(ns));
      }
      scheduleRefresh();
    };
    block.querySelectorAll(".yr-mod").forEach(function (cb) {
      cb.onchange = function () {
        if (!s.mods) s.mods = {};
        s.mods[cb.dataset.mod] = cb.checked;
        scheduleRefresh();
      };
    });
    return block;
  }

  // full rebuild — used only on example load / reset (not on keystrokes)
  function renderStrings() {
    strWrap.innerHTML = "";
    state.strings.forEach(function (s) { strWrap.appendChild(buildStringBlock(s)); });
  }

  $("yr-add-str").onclick = function () {
    var ns = { id: nextStringId(), type: "text", value: "", mods: {} };
    state.strings.push(ns);
    strWrap.appendChild(buildStringBlock(ns));
    scheduleRefresh();
  };

  // ── condition presets ──
  var presetWrap = $("yr-cond-presets");
  presetWrap.innerHTML = COND_PRESETS.map(function (p, i) {
    return '<button type="button" class="yr-chip" data-p="' + i + '">' + esc(p[0]) + "</button>";
  }).join("");
  presetWrap.onclick = function (e) {
    var b = e.target.closest("button[data-p]");
    if (!b) return;
    var snippet = COND_PRESETS[+b.dataset.p][1];
    var ta = $("yr-condition");
    var cur = ta.value.trim();
    // insert at cursor if there is a real selection, else append sensibly
    var start = ta.selectionStart, end = ta.selectionEnd;
    if (typeof start === "number" && (start !== end || cur !== "")) {
      ta.value = ta.value.slice(0, start) + snippet + ta.value.slice(end);
    } else {
      ta.value = snippet;
    }
    state.condition = ta.value;
    scheduleRefresh();
    ta.focus();
  };

  // ── sync all form fields from state (for example load / reset) ──
  function syncForm() {
    $("yr-name").value = state.name;
    $("yr-tags").value = state.tags;
    $("yr-desc").value = state.description;
    $("yr-author").value = state.author;
    $("yr-date").value = state.date;
    $("yr-ref").value = state.reference;
    $("yr-hash").value = state.hash;
    $("yr-condition").value = state.condition;
    renderStrings();
    flushRefresh();
  }

  // ── examples menu ──
  var exMenu = $("yr-example-menu");
  var exList = examples();
  exMenu.innerHTML = exList.map(function (e, i) {
    return '<button type="button" data-ex="' + i + '">' + esc(e.name) + "</button>";
  }).join("");
  $("yr-example-btn").onclick = function (e) { e.stopPropagation(); exMenu.classList.toggle("open"); };
  document.addEventListener("click", function onDoc() { if (!exMenu.isConnected) { document.removeEventListener("click", onDoc); return; } exMenu.classList.remove("open"); });
  exMenu.onclick = function (e) {
    var b = e.target.closest("button[data-ex]");
    if (!b) return;
    e.stopPropagation();
    exMenu.classList.remove("open");
    var ex = exList[+b.dataset.ex];
    state = JSON.parse(JSON.stringify(ex.state));
    touched = true;
    syncForm();
    toast("Loaded example: " + ex.name);
  };

  // ── reset ──
  $("yr-reset").onclick = function () {
    state = emptyModel();
    touched = false;
    syncForm();
    toast("Reset to an empty rule");
  };

  // ── actions ──
  $("yr-validate").onclick = function () {
    touched = true;
    flushRefresh();
  };

  $("yr-copy").onclick = function () {
    var text = buildYara(state);
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () { toast("YARA rule copied to clipboard"); },
        function () { toast("Copy failed — select the text manually"); });
    } else {
      toast("Clipboard unavailable — select the text manually");
    }
  };

  $("yr-download").onclick = function () {
    var text = buildYara(state);
    var slug = (state.name || "yara_rule").replace(/[^A-Za-z0-9_]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 60) || "yara_rule";
    var blob = new Blob([text], { type: "text/plain" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url; a.download = slug + ".yar";
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
    toast("Downloaded " + slug + ".yar");
  };

  // initial paint (pristine form: preview shown, findings suppressed until first edit)
  syncForm();
}
